// Processar dados de erro do Error Trigger
const input = $input.first().json;

// Extrair dados do contexto de erro do n8n
const execution = input.execution || {};
const workflow = input.workflow || execution.workflowData || {};
const errorData = execution.error || input.error || {};

// Extrair informacoes
const executionId = execution.id || input.executionId || 'unknown';
const workflowId = workflow.id || input.workflowId || 'unknown';
const workflowName = workflow.name || input.workflowName || 'Unknown Workflow';

// Tentar extrair o node que falhou
let nodeName = 'Unknown Node';
if (errorData.node) {
  nodeName = errorData.node.name || errorData.node;
} else if (input.node) {
  nodeName = input.node.name || input.node;
}

// Extrair mensagem de erro
let errorMessage = 'Unknown error';
if (errorData.message) {
  errorMessage = errorData.message;
} else if (typeof errorData === 'string') {
  errorMessage = errorData;
} else if (input.message) {
  errorMessage = input.message;
}

// Classificar tipo de erro baseado na mensagem
let errorType = 'UNKNOWN';
const msgLower = errorMessage.toLowerCase();
if (msgLower.includes('timeout') || msgLower.includes('rate limit') || msgLower.includes('token')) {
  errorType = 'AI';
} else if (msgLower.includes('duplicate') || msgLower.includes('constraint') || msgLower.includes('foreign key') || msgLower.includes('supabase')) {
  errorType = 'DATABASE';
} else if (msgLower.includes('api') || msgLower.includes('401') || msgLower.includes('403') || msgLower.includes('telegram')) {
  errorType = 'API';
} else if (msgLower.includes('parse') || msgLower.includes('json') || msgLower.includes('syntax')) {
  errorType = 'PARSE';
} else if (msgLower.includes('network') || msgLower.includes('econnrefused') || msgLower.includes('timeout')) {
  errorType = 'NETWORK';
}

// Severidade baseada no workflow
const severity = 'CRITICAL';

const now = new Date().toISOString();
const displayDate = new Date().toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

const typeEmojis = {
  'AI': '🤖',
  'DATABASE': '🗄️',
  'API': '📡',
  'PARSE': '📝',
  'NETWORK': '🌐',
  'VALIDATION': '⚠️',
  'UNKNOWN': '❓'
};

const severityEmojis = {
  'CRITICAL': '🚨',
  'WARNING': '⚠️',
  'INFO': 'ℹ️'
};

// Gerar hash para deduplicacao
const hashSource = `${workflowId}:${nodeName}:${errorType}:${errorMessage.substring(0, 100)}`;
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).padStart(16, '0');
}
const errorHash = simpleHash(hashSource);

return [{
  json: {
    execution_id: executionId,
    workflow_id: workflowId,
    workflow_name: workflowName,
    node_name: nodeName,
    error_type: errorType,
    severity: severity,
    error_message: errorMessage,
    error_code: errorData.code || null,
    error_stack: errorData.stack || null,
    input_data: null,
    context: {
      mode: execution.mode || 'unknown',
      retryOf: execution.retryOf || null
    },
    error_hash: errorHash,
    timestamp: now,
    display_date: displayDate,
    type_emoji: typeEmojis[errorType] || '❓',
    severity_emoji: severityEmojis[severity] || '🚨',
    dedup_threshold: new Date(Date.now() - 30 * 60 * 1000).toISOString()
  }
}];

// Preparar mensagem formatada para Telegram
const erro = $('PROCESSAR ERRO').first().json;

let message = `${erro.severity_emoji} *ERRO ${erro.severity} - BLOG SYSTEM*\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n\n`;

message += `📋 *Workflow:* ${erro.workflow_name}\n`;
message += `🔧 *Node:* ${erro.node_name}\n`;
message += `${erro.type_emoji} *Tipo:* ${erro.error_type}\n`;
message += `⏰ *Horario:* ${erro.display_date}\n\n`;

message += `❌ *Erro:*\n`;
const errorText = erro.error_message.substring(0, 400);
message += `${errorText}${erro.error_message.length > 400 ? '...' : ''}\n\n`;

if (erro.context && Object.keys(erro.context).length > 0) {
  message += `📝 *Contexto:*\n`;
  for (const [key, value] of Object.entries(erro.context)) {
    const displayValue = typeof value === 'object' ? JSON.stringify(value).substring(0, 80) : String(value).substring(0, 80);
    message += `├─ ${key}: ${displayValue}\n`;
  }
  message += `\n`;
}

message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `🆔 Execution: ${erro.execution_id}`;

return [{
  json: {
    chat_id: '8375309778',
    text: message,
    parse_mode: 'Markdown'
  }
}];
